const pageInfo = await browserjs(tabId, () => {
  // Check sort options
  const sortSelect = document.querySelector('select[name*="sort"], .sort-by select, [data-sort]');
  const sortOptions = sortSelect ? Array.from(sortSelect.options).map(o => ({ text: o.text, value: o.value, selected: o.selected })) : null;

  // Check filter buttons / sections
  const filterElements = Array.from(document.querySelectorAll('button, .filter, [data-filter]')).map(el => ({
    tag: el.tagName,
    text: el.textContent.trim().replace(/\s+/g, ' '),
    className: el.className
  })).filter(f => f.text.toLowerCase().includes('sort') || f.text.toLowerCase().includes('filter') || f.text.toLowerCase().includes('color') || f.text.toLowerCase().includes('size'));

  // Also check products listed on the page
  const productTiles = Array.from(document.querySelectorAll('.product-tile, [data-pid], .product')).map(el => {
    return {
      title: el.querySelector('.product-title, .pdp-link, h3, h2')?.textContent?.trim().replace(/\s+/g, ' '),
      subtitle: el.querySelector('.product-subtitle, .secondary-name')?.textContent?.trim().replace(/\s+/g, ' '),
      price: el.querySelector('.price, .sales')?.textContent?.trim().replace(/\s+/g, ' '),
      href: el.querySelector('a')?.href
    };
  });

  return {
    title: document.title,
    sortOptions,
    filterElements: filterElements.slice(0, 20),
    productCount: productTiles.length,
    firstProducts: productTiles.slice(0, 10)
  };
});

