const pdpInfo = await browserjs(tabId, () => {
  // Product title and color
  const title = document.querySelector('.product-name, h1')?.textContent?.trim();
  const colorName = document.querySelector('.color-value, .selected-color, [data-attr="color"] .value')?.textContent?.trim();

  // Available colors
  const colorSwatches = Array.from(document.querySelectorAll('.swatch-color, [data-attr="color"] a, .color-variation a, [data-tau="variation_color_swatch"]')).map(el => ({
    title: el.getAttribute('title') || el.getAttribute('aria-label') || el.textContent?.trim(),
    selected: el.classList.contains('selected') || el.getAttribute('aria-selected') === 'true' || el.classList.contains('active')
  }));

  // Available sizes
  const sizeElements = Array.from(document.querySelectorAll('[data-tau="variation_size_swatch"], .size-swatches a, .size-swatches button, [data-attr="size"] button, [data-attr="size"] a, .b-swatch-size, .b-size-swatch')).map(el => ({
    text: el.textContent?.trim().replace(/\s+/g, ' '),
    ariaLabel: el.getAttribute('aria-label'),
    title: el.getAttribute('title'),
    value: el.getAttribute('data-value'),
    disabled: el.disabled || el.classList.contains('disabled') || el.classList.contains('m-disabled') || el.getAttribute('aria-disabled') === 'true',
    selected: el.classList.contains('selected') || el.getAttribute('aria-selected') === 'true' || el.classList.contains('m-selected')
  }));

  // Width options
  const widthElements = Array.from(document.querySelectorAll('[data-tau="variation_width_swatch"], .width-swatches a, .width-swatches button, [data-attr="width"] button, [data-attr="width"] a, .b-swatch-width')).map(el => ({
    text: el.textContent?.trim().replace(/\s+/g, ' '),
    ariaLabel: el.getAttribute('aria-label'),
    value: el.getAttribute('data-value'),
    selected: el.classList.contains('selected') || el.classList.contains('m-selected')
  }));

  // Add to cart button
  const addToCartBtn = document.querySelector('.add-to-cart, [data-tau="add_to_cart"], button[data-action="add-to-cart"], .b-add_to_bag-button');

  return {
    title,
    colorName,
    colorSwatches: colorSwatches.slice(0, 10),
    sizeElements,
    widthElements,
    addToCartBtn: addToCartBtn ? {
      text: addToCartBtn.textContent?.trim(),
      disabled: addToCartBtn.disabled,
      className: addToCartBtn.className
    } : null
  };
});

console.log(JSON.stringify(pdpInfo, null, 2));

